function color(graph, m) {
  const assigned = new Map();

  function ok(node, c) {
    for (const other of graph.neighbors(node)) {
      if (assigned.get(other) === c) return false;
    }
    return true;
  }

  function solve(index) {
    if (index === graph.nodes.length) return true;   // all done

    const node = graph.nodes[index];
    for (let c = 0; c < m; c++) {
      if (!ok(node, c)) continue;

      assigned.set(node, c);
      if (solve(index + 1)) return true;   // a success bubbles all the way up
      assigned.delete(node);               // that color failed, undo it
    }

    return false;                          // no color worked here
  }

  return solve(0) ? assigned : null;
}

