    def ok(node, c):
        return all(assigned.get(other) != c for other in graph.neighbors(node))

    def solve(index):
        if index == len(graph.nodes):
            return True                    # all done

        node = graph.nodes[index]
        for c in range(m):
            if not ok(node, c):
                continue

            assigned[node] = c
            if solve(index + 1):
                return True                # a success bubbles all the way up
            del assigned[node]             # that color failed, undo it

        return False                       # no color worked here

    return assigned if solve(0) else None
